/**
 * Local-First Bundle Rendering
 * Stages all deployment artifacts (Compose files, .env, scripts) into a local temp directory
 * before any infrastructure is provisioned or network calls are made.
 */

import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { stripOperatorSecretLines } from '../config-registry.js';
import { escapeDotenv } from '../shell.js';
import { DNS01_OVERRIDE_FILE, dnsChallengeEnv } from './acme.js';
import { registryEnsureShell } from './compose/registry-config.js';

/**
 * The two compose files EVERY deployed server carries, in `-f` order.
 * `docker-compose.prod.yml` must follow the base file — it overrides it.
 */
export const COMPOSE_BASE_FILES = ['docker-compose.yml', 'docker-compose.prod.yml'];

/**
 * The replication overlay. Written only onto compose-ha nodes and appended
 * LAST, at runtime, by whoever composes a `-f` set (reconcile.sh, the systemd
 * unit, the failover db-recreate) — see `renderReconcileScript`.
 */
export const COMPOSE_REPLICATION_OVERLAY = 'docker-compose.replication.yml';

/**
 * Every OPTIONAL compose file a deployed server can carry, in `-f` order, each
 * with the bundle option that selects it. `renderBundle` copies a file to the
 * server only when its option is on (see rootFiles below), so the two stay in
 * step by construction rather than by convention.
 *
 * NOTE this is not the only compose-flag list in the tree — `compose/index.js`
 * and `scale.js` carry their own for other purposes. This one is specifically
 * the DEPLOY-time `-f` set that `composeFileFlags` renders into reconcile.sh and
 * the systemd unit.
 */
const COMPOSE_OPTIONAL_FILES = [
  { file: DNS01_OVERRIDE_FILE, when: (o) => o.dnsChallenge },
  { file: 'docker-compose.observability.yml', when: (o) => o.observability },
  { file: 'docker-compose.observability.prod.yml', when: (o) => o.observability },
  { file: 'docker-compose.n8n.yml', when: (o) => o.n8n },
  { file: 'docker-compose.n8n.prod.yml', when: (o) => o.n8n },
  { file: 'docker-compose.metabase.yml', when: (o) => o.metabase },
  { file: 'docker-compose.metabase.prod.yml', when: (o) => o.metabase },
  { file: 'docker-compose.redis.yml', when: (o) => o.redis },
  { file: 'docker-compose.redis.prod.yml', when: (o) => o.redis },
];

/**
 * Render the reconcile.sh script
 */
export function renderReconcileScript(projectName, composeFlags, isFast = false) {
  // On compose-ha servers the replication overlay (docker-compose.replication.yml)
  // publishes port 5433 → db:5432 for pg_basebackup / streaming replication.
  // reconcile.sh is baked with static composeFlags at deploy time, so we embed a
  // shell conditional here that appends the overlay at runtime when present.
  // On single-server compose the file never exists, so this is a safe no-op.
  const replOverlayFlag = `$([ -f ${COMPOSE_REPLICATION_OVERLAY} ] && echo '-f ${COMPOSE_REPLICATION_OVERLAY}')`;

  const pullStep = isFast
    ? ''
    : `
# 2. Pull latest images if needed
echo "Pulling images..."
docker compose ${composeFlags} ${replOverlayFlag} pull --quiet --policy missing --ignore-buildable || true
`;

  return `#!/bin/bash
set -e

# Declarative Compose Reconciler
# Generated by Vibecarbon

PROJECT_DIR="/opt/${projectName}"
cd "$PROJECT_DIR"

echo "Reconciling project: ${projectName}..."

echo "File layout in $(pwd):"
ls -R | grep ":$" | sed 's/:$//' | xargs -I {} sh -c "echo '{}:' && ls {} | head -n 5"

if [ -f ".env" ]; then
  echo "Found .env file"
  # Don't print secrets, but check for existence of keys
  grep -E "^(S3_BUCKET|PROJECT_NAME|APP_IMAGE)=" .env | sed 's/=.*$/=***/'
else
  echo "WARNING: .env file NOT FOUND in $(pwd)"
fi


# 1. Self-heal containers pointing at a removed network
# When a network's definition changes (e.g. an IPAM subnet pin arriving in the
# base file), compose stops every attached container, removes the network and
# creates a replacement — but only recreates containers whose own config-hash
# changed. The rest keep endpoint config referencing the dead network ID and
# can never start again ("network <id> not found"), so every subsequent up
# fails until they're removed. Such containers are unstartable by definition;
# removing them is safe and the up step recreates them on the current network.
echo "Checking for containers attached to removed networks..."
live_network_ids="$(docker network ls -q --no-trunc)"
for container_id in $(docker ps -aq --filter "label=com.docker.compose.project=${projectName}"); do
  for network_id in $(docker inspect --format '{{range .NetworkSettings.Networks}}{{.NetworkID}} {{end}}' "$container_id" 2>/dev/null); do
    if ! printf '%s\\n' "$live_network_ids" | grep -qx "$network_id"; then
      container_name="$(docker inspect --format '{{.Name}}' "$container_id" 2>/dev/null || echo "$container_id")"
      echo "Removing \${container_name#/}, attached to removed network \${network_id:0:12}"
      docker rm -f "$container_id" > /dev/null || true
      break
    fi
  done
done

# 1b. Self-heal the per-server image registry (warm-redeploy layer transfer).
# Standalone container outside the compose stack; --restart unless-stopped
# covers reboots, this covers removal/wedge. Runs AFTER dockerhubLogin in the
# deploy plan, so this ensure's Hub pull is authenticated even when the
# deploy-time (pre-login) ensure was rate-limited. Additive — guarded so a
# registry failure never breaks the rest of reconcile.
# Emitted for EVERY compose mode and both compose-ha nodes on purpose, not
# just the "local" mode that pushes — see registryEnsureShell()'s docblock
# for the cost measurements and the mode-is-not-durable reasoning.
${registryEnsureShell()}
${pullStep}
# 3. Re-create containers if state differs
#
# RCA instrumentation (2026-08-06 warm recreate-wave, open): preserve the exact
# rendered config every reconcile plans against — first = the cold deploy's
# view, last = the most recent. When a warm up unexpectedly recreates services
# despite byte-identical inputs, \`diff .vc-render-first.yaml
# .vc-render-last.yaml\` on the server names the drifting keys directly.
# Rendered values are no more sensitive than .env in this same root-only dir.
echo "Updating containers..."
docker compose ${composeFlags} ${replOverlayFlag} config > .vc-render-last.yaml 2>/dev/null || true
[ -f .vc-render-first.yaml ] || cp .vc-render-last.yaml .vc-render-first.yaml 2>/dev/null || true
docker compose ${composeFlags} ${replOverlayFlag} up -d --remove-orphans

# 4. Ensure systemd service is active (if applicable)
if [ -f "/etc/systemd/system/${projectName}.service" ]; then
  echo "Ensuring systemd service is active..."
  systemctl daemon-reload
  systemctl enable "${projectName}.service"
fi

echo "Reconciliation complete."
`;
}

/**
 * Render the systemd service unit
 */
export function renderSystemdUnit(projectName, composeFlags, _isFast = false) {
  // Same runtime replication-overlay conditional as reconcile.sh: compose-ha
  // nodes carry docker-compose.replication.yml (5433 publish + repl-gateway),
  // and a unit up/down without it recreates db minus the replication port and
  // --remove-orphans deletes repl-gateway (defined only in the overlay) — a
  // node reboot would silently break replication transport. systemd has no
  // command substitution, so the command runs through bash; `$$` passes a
  // literal `$` through systemd's expansion (verified on systemd 255).
  const replOverlayFlag = `$$([ -f ${COMPOSE_REPLICATION_OVERLAY} ] && echo "-f ${COMPOSE_REPLICATION_OVERLAY}")`;
  return `[Unit]
Description=Vibecarbon Project: ${projectName}
After=docker.service
Requires=docker.service

[Service]
Type=oneshot
RemainAfterExit=yes
WorkingDirectory=/opt/${projectName}
ExecStart=/bin/bash -c 'docker compose ${composeFlags} ${replOverlayFlag} up -d --remove-orphans'
ExecStop=/bin/bash -c 'docker compose ${composeFlags} ${replOverlayFlag} down'
Restart=on-failure

[Install]
WantedBy=multi-user.target
`;
}

/**
 * Build the compose files flags string
 */
function composeFileFlags(options = {}) {
  // Base first, then each enabled optional overlay in COMPOSE_OPTIONAL_FILES
  // order — the DNS-01 override must follow prod.yml so it replaces the Traefik
  // command, and every `.prod.yml` must follow its own base overlay.
  const files = [
    ...COMPOSE_BASE_FILES,
    ...COMPOSE_OPTIONAL_FILES.filter((e) => e.when(options)).map((e) => e.file),
  ];
  return files.flatMap((f) => ['-f', f]).join(' ');
}

/**
 * Render the Traefik dynamic-config file that instructs Traefik to obtain and
 * serve ONE cert for the entire deploy as the TLS default store entry.
 *
 * With `defaultGeneratedCert`, Traefik proactively requests a single cert via
 * the named resolver at startup and serves it by default for every TLS router
 * that does NOT carry an explicit `tls.certresolver` label. All our production
 * routers use `tls=true` without a resolver — they all get this cert via SNI.
 *
 * Challenge-type differences:
 *   - DNS-01 (managed DNS — cloudflare/hetzner): `sans: ["*.${domain}"]`.
 *     One wildcard cert covers all subdomains, no per-subdomain ACME orders.
 *   - HTTP-01 (manual DNS): wildcards require DNS-01 (LE policy), so we list
 *     the explicit subdomains that are active for this deploy instead.
 *     `main` stays `${domain}` (the app root); `sans` lists api/studio/dashboard
 *     plus any enabled feature subdomains (grafana/prometheus, n8n, metabase).
 *
 * The file is written into `volumes/traefik/` which is already bind-mounted
 * as `/etc/traefik/dynamic:ro`. Traefik hot-reloads files from that dir.
 * Multiple files in the dir coexist fine; this file adds only a top-level
 * `tls:` key that has no overlap with the `http:` keys in middlewares.yml.
 *
 * @param {{domain: string, dnsChallenge: boolean, features?: {observability?: boolean, n8n?: boolean, metabase?: boolean}}} opts
 * @returns {string} YAML string suitable for writing to `volumes/traefik/tls-default.yml`
 */
export function renderTraefikDefaultCert({ domain, dnsChallenge, features = {} }) {
  // The default store cert covers the SUBDOMAINS only. The app at the bare apex
  // (`${domain}`) gets its OWN single-domain cert via the app router's
  // `tls.certresolver` label — it is deliberately NOT in this cert.
  //
  // Why split apex off the wildcard: a cert for [`${domain}`, `*.${domain}`] has
  // TWO ACME authorizations that BOTH validate via the SAME TXT record
  // `_acme-challenge.${domain}`, so both challenge values must be present there
  // simultaneously. The Hetzner lego DNS provider REPLACES the TXT rrset instead
  // of holding both values, so one authorization always fails with
  // "403 unauthorized :: Incorrect TXT record". (Cloudflare holds both and
  // worked — RCA 2026-06-01, compose e2e wildcard verify-deploy.) As two
  // SEPARATE single-authz certs (apex via the app router, `*.${domain}` here),
  // Traefik obtains them serially, so `_acme-challenge.${domain}` only ever
  // needs one value at a time — robust on Hetzner AND Cloudflare.
  let main;
  let sans;
  if (dnsChallenge) {
    // DNS-01: one wildcard covers every subdomain (most general level).
    main = `*.${domain}`;
    sans = [];
  } else {
    // HTTP-01: wildcards require DNS-01 (LE policy), so enumerate the active
    // subdomains. `studio` and `dashboard` always exist; the rest are
    // feature-gated. The apex (app + Hono API + Kong path-routes) is covered
    // by its own router cert, not here.
    const subs = ['dashboard'];
    if (features.observability) subs.push('grafana', 'prometheus');
    if (features.n8n) subs.push('n8n');
    if (features.metabase) subs.push('metabase');
    main = `studio.${domain}`;
    sans = subs.map((s) => `${s}.${domain}`);
  }

  const lines = [
    'tls:',
    '  stores:',
    '    default:',
    '      defaultGeneratedCert:',
    '        resolver: letsencrypt',
    '        domain:',
    `          main: "${main}"`,
  ];
  if (sans.length) {
    lines.push('          sans:');
    for (const d of sans) lines.push(`            - "${d}"`);
  }

  return `# Traefik default TLS certificate — generated by Vibecarbon at deploy time.
#
# Serves as the default cert for ALL TLS routers carrying \`tls=true\` without an
# explicit certresolver (SNI fallback). Covers the SUBDOMAINS; the apex app gets
# its own cert via the app router's \`tls.certresolver\`.
#
# DNS-01 (cloudflare/hetzner): one wildcard cert covering every subdomain.
# HTTP-01 (manual DNS): explicit subdomain SANs (LE policy forbids wildcards).
${lines.join('\n')}
`;
}

/**
 * Render the deployment bundle to a local temp directory
 * @param {string} projectName
 * @param {object} options
 * @returns {string} The path to the staged bundle directory
 */
export function renderBundle(projectName, options = {}) {
  const cwd = process.cwd();
  const stageDir = mkdtempSync(join(tmpdir(), 'vc-deploy-bundle-'));

  // Core Docker files
  const rootFiles = [
    'docker-compose.yml',
    'docker-compose.prod.yml',
    'Dockerfile',
    '.dockerignore',
  ];
  if (options.observability) {
    rootFiles.push('docker-compose.observability.yml', 'docker-compose.observability.prod.yml');
  }
  if (options.n8n) {
    rootFiles.push('docker-compose.n8n.yml', 'docker-compose.n8n.prod.yml');
  }
  if (options.metabase) {
    rootFiles.push('docker-compose.metabase.yml', 'docker-compose.metabase.prod.yml');
  }
  if (options.redis) rootFiles.push('docker-compose.redis.yml', 'docker-compose.redis.prod.yml');
  if (options.dnsChallenge) rootFiles.push(DNS01_OVERRIDE_FILE);

  for (const file of rootFiles) {
    const src = join(cwd, file);
    if (existsSync(src)) {
      if (options.verbose) console.log(`[bundle] Copying ${file}`);
      cpSync(src, join(stageDir, file));
    }
  }

  // Render .env locally with overrides
  const localEnvPath = join(cwd, '.env');
  let envContent = '';
  if (existsSync(localEnvPath)) {
    envContent = readFileSync(localEnvPath, 'utf-8');
  }
  // Defense-in-depth: this baseline is echoed into the bundle line-for-line
  // below for any key without an explicit override, so an operator-secret
  // key must never survive the read — see stripOperatorSecretLines' doc for
  // why this doesn't touch envOverrides (S3/DNS-01/scale-replay stay live).
  envContent = stripOperatorSecretLines(envContent);

  const envOverrides = { ...(options.envOverrides || {}) };
  if (options.domain) {
    envOverrides.DOMAIN = options.domain;
    envOverrides.ACME_EMAIL = `admin@${options.domain}`;
    // Single public origin: the apex serves the SPA, the Hono /api, AND the
    // Supabase gateway (Traefik path-routes /auth/v1|/rest/v1|/realtime/v1|
    // /storage/v1 to Kong). SITE_URL is that one origin — GoTrue redirect
    // config, billing return URLs, and CSP/CORS all derive from it.
    envOverrides.SITE_URL = `https://${options.domain}`;
    envOverrides.SUPABASE_URL = 'http://kong:8000';
  }
  if (options.image) {
    envOverrides.APP_IMAGE = options.image;
  }
  if (options.s3) {
    envOverrides.S3_ACCESS_KEY = options.s3.accessKey;
    envOverrides.S3_SECRET_KEY = options.s3.secretKey;
    envOverrides.S3_REGION = options.s3.region;
    envOverrides.S3_ENDPOINT = options.s3.endpoint;
    envOverrides.S3_BUCKET = options.s3.bucket;
  }
  if (options.backupS3) {
    envOverrides.S3_BACKUP_BUCKET = options.backupS3.bucket;
  }
  if (projectName) {
    envOverrides.PROJECT_NAME = projectName;
  }
  // DNS-01: lego reads ACME_DNS_PROVIDER + the matching provider token from the
  // server .env (consumed by docker-compose.dns01.prod.yml's Traefik env).
  if (options.dnsChallenge) {
    // null for a non-DNS-01 provider; Object.assign ignores it.
    Object.assign(envOverrides, dnsChallengeEnv(options.dnsProvider, options.dnsToken));
  }

  // Merge overrides into local copy
  const lines = envContent.split('\n');
  const seen = new Set();
  const merged = lines.map((line) => {
    const m = line.match(/^([A-Z_][A-Z0-9_]*)=/);
    if (m && envOverrides[m[1]] !== undefined) {
      seen.add(m[1]);
      return `${m[1]}=${escapeDotenv(envOverrides[m[1]])}`;
    }
    return line;
  });
  for (const [k, v] of Object.entries(envOverrides)) {
    if (!seen.has(k)) merged.push(`${k}=${escapeDotenv(v)}`);
  }
  writeFileSync(join(stageDir, '.env'), merged.join('\n'));

  const isFast = Boolean(options.image?.endsWith(':local'));
  const flags = composeFileFlags(options);
  writeFileSync(join(stageDir, 'reconcile.sh'), renderReconcileScript(projectName, flags, isFast), {
    mode: 0o755,
  });
  writeFileSync(
    join(stageDir, `${projectName}.service`),
    renderSystemdUnit(projectName, flags, isFast),
  );

  const copyDirIfExist = (srcDir, destDir) => {
    const src = join(cwd, srcDir);
    if (existsSync(src)) {
      if (options.verbose) console.log(`[bundle] Copying ${srcDir} to ${destDir}`);
      cpSync(src, join(stageDir, destDir), { recursive: true });
    } else {
      if (options.verbose) console.log(`[bundle] Skipping ${srcDir} (not found)`);
    }
  };

  copyDirIfExist('db', 'db');
  copyDirIfExist('volumes/db', 'volumes/db');
  // Supavisor tenant seed — bind-mounted by docker-compose.prod.yml. Missing
  // from the bundle = Docker auto-creates a directory over it on the server
  // and the pooler crash-loops on `cat: /etc/pooler/pooler.exs: Is a
  // directory` (same class as the functions/ note below).
  copyDirIfExist('volumes/pooler', 'volumes/pooler');
  copyDirIfExist('supabase/migrations', 'supabase/migrations');
  copyDirIfExist('volumes/kong', 'volumes/kong');
  // Edge functions: docker-compose.prod.yml bind-mounts ./functions and starts
  // the edge-runtime with `--main-service /home/deno/functions/main`. If this
  // isn't bundled, the mount auto-creates an empty dir on the server and the
  // runtime crash-loops with "could not find an appropriate entrypoint". The
  // template ships a stub at functions/main/index.ts. RCA: prod-1 2026-05-26.
  copyDirIfExist('functions', 'functions');

  // volumes/traefik/ — dynamic-config directory mounted into Traefik.
  // Always ensure the dir exists in the bundle so Traefik's file provider
  // has a valid mount target even if the source dir is absent.
  mkdirSync(join(stageDir, 'volumes', 'traefik'), { recursive: true });

  const traefikMiddlewares = join(cwd, 'volumes', 'traefik', 'middlewares.yml');
  if (existsSync(traefikMiddlewares)) {
    cpSync(traefikMiddlewares, join(stageDir, 'volumes', 'traefik', 'middlewares.yml'));
  }

  // Render tls-default.yml only when a domain is known (production deploys).
  // This instructs Traefik to proactively obtain ONE cert for the deploy and
  // serve it as the default for all TLS routers via SNI. DNS-01 deploys get
  // a wildcard SAN (*.${domain}); HTTP-01 deploys get explicit subdomain SANs.
  // The file coexists with middlewares.yml — both live under the same `tls:`
  // / `http:` top-level keys respectively; Traefik merges all files in the dir.
  if (options.domain) {
    const tlsDefaultYaml = renderTraefikDefaultCert({
      domain: options.domain,
      dnsChallenge: Boolean(options.dnsChallenge),
      features: {
        observability: options.observability,
        n8n: options.n8n,
        metabase: options.metabase,
      },
    });
    writeFileSync(join(stageDir, 'volumes', 'traefik', 'tls-default.yml'), tlsDefaultYaml);
    if (options.verbose) console.log('[bundle] Rendered volumes/traefik/tls-default.yml');
  }

  copyDirIfExist('backup', 'backup');
  if (options.n8n) copyDirIfExist('volumes/n8n', 'volumes/n8n');
  if (options.metabase) copyDirIfExist('volumes/metabase', 'volumes/metabase');

  if (options.observability) {
    copyDirIfExist('prometheus', 'prometheus');
    copyDirIfExist('grafana', 'grafana');
    for (const subdir of ['prometheus', 'grafana', 'loki', 'promtail']) {
      copyDirIfExist(`volumes/${subdir}`, `volumes/${subdir}`);
    }
  }

  return stageDir;
}
